    return undefined;
  }
  return {
    from: row.from,
    to: row.to,
    toSlug: row.toSlug,
    profile: row.profile,
    prompt: row.prompt,
    paths,
    kind: "a2a_handoff",
    mode: "async",
    onBusy: "queue",
    idempotencyKey: row.idempotencyKey,
  };
}

export function stripePacketHasNoInvoiceCandidate(packet: unknown): boolean {
  if (!isRecord(packet)) {
    return false;
