  mkdirSync(dirname(filePath), {recursive: true});
  const tmpPath = `${filePath}.tmp.${process.pid}`;
  writeFileSync(tmpPath, `${JSON.stringify(payload, null, 2)}\n`, {encoding: 'utf8'});
  renameSync(tmpPath, filePath);
}

